    if (!D) return st.s === 'err' ? dbFallback('bills', 'billsec', title, 'Could not load bills' + (st.msg ? ': ' + esc(st.msg) : '') + '.', 'err')
      : dbFallback('bills', 'billsec', title, 'Loading bills\u2026', 'load');
