    ['name', 'category', 'serving', 'ingredients', 'price', 'cal', 'protein', 'carbs', 'fat'].forEach(function (k) { if (p[k] !== '') { maF(k).value = p[k]; got++; } });
    maRead(); maDraftSave(); maUi(); maChips();
