  function pjGet(k, d) { try { var v = JSON.parse(localStorage.getItem(k)); return v == null ? d : v; } catch (e) { return d; } }
  function pjSet(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
