      if (state.finKind !== 'overview') return;
      if (!err) ov.fin = { s: 'ok', data: data };
      else if (err.na) ov.fin = { s: 'na' };
      else if (err instanceof AuthError) { setPc(''); return lock('Passcode changed. Enter the new one.'); }
