    if (u === 'ml' || u === 'milliliter' || u === 'milliliters') return { n: q.n, k: 'ml' };
    if (u === 'l' || u === 'liter' || u === 'liters') return { n: q.n * 1000, k: 'ml' };
    if (u === 'floz' || u === 'fl') return { n: q.n * 29.5735, k: 'ml' };
