    auto: { 2: ['fullA', 'fullB'], 3: ['lowerA', 'upperA', 'fullA'], 4: ['lowerA', 'upperA', 'lowerB', 'upperB'], 5: ['lowerA', 'upperA', 'fullA', 'lowerB', 'upperB'] },
