    if (hit >= 0) l[hit] = c; else l.push(c);
    l.sort(function (a, b) { return a.status === b.status ? a.name.toLowerCase().localeCompare(b.name.toLowerCase()) : (a.status === 'active' ? -1 : 1); });
    pt.at = Date.now();
