    var embedP = d.indexOf('data:image/png') === 0 ? out.embedPng(pcDataUrlToBytes(d))
      : (/^data:image\/jpe?g/.test(d) ? out.embedJpg(pcDataUrlToBytes(d)) : pcToJpegBytes(d).then(function (b) { return out.embedJpg(b); }));
