  /* -- PDF delivery: Web Share (phones: Files / Drive / Mail) + download -- */
  function pcIsPhone() {
    try { if (window.matchMedia && matchMedia('(pointer: coarse)').matches) return true; } catch (e) {}
    return /iPhone|iPad|iPod|Android/i.test(navigator.userAgent || '');
  }
  function pcCanShareFiles(file) {
    try {
      if (!navigator.share || !navigator.canShare) return false;
      var f = file || new File([new Blob(['%PDF-1.4'], { type: 'application/pdf' })], 'check.pdf', { type: 'application/pdf' });
      return !!navigator.canShare({ files: [f] });
    } catch (e) { return false; }
  }
  function pcFmtBytes(n) { return n >= 1048576 ? (n / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round(n / 1024)) + ' KB'; }
  function pcPdfSheet() {
    var root = $('screen-pc'); if (!root) return;
    var x = pc.exp; if (!x) return;
    var el = $('pc-pdf-sheet');
    if (!el) { el = document.createElement('div'); el.id = 'pc-pdf-sheet'; el.className = 'pcpdfsheet'; el.setAttribute('role', 'dialog'); el.setAttribute('aria-label', 'PDF export'); root.appendChild(el); }
    var h;
    if (x.busy) h = '<div class="pcpdfmsg"><b>Building PDF\u2026</b><span>Made on this device. The first time also loads the PDF tools.</span></div>';
    else if (x.error) h = '<div class="pcpdfmsg bad"><b>PDF failed</b><span>' + esc(x.error) + '</span></div><div class="pcpdfbtns"><button type="button" class="navbtn pcmini" data-pc="pdf-close">Close</button></div>';
    else {
      h = '<div class="pcpdfmsg"><b>PDF ready</b><span>' + esc(x.name) + ' \u00b7 ' + x.pages + ' page' + (x.pages === 1 ? '' : 's') + ' \u00b7 ' + pcFmtBytes(x.blob.size) + '</span>' +
        '<span class="pcpdfnote" id="pc-pdf-note">' + esc(x.msg || x.note || '') + '</span></div>' +
        '<div class="pcpdfbtns">' +
        (x.canShare ? '<button type="button" class="navbtn pcmini pcpdfgo" data-pc="pdf-share">' + (x.mode === 'mail' ? 'Share PDF to Mail' : 'Share / Save to Files') + '</button>' : '') +
        '<button type="button" class="navbtn pcmini" data-pc="pdf-download">Download</button>' +
        '<button type="button" class="navbtn pcmini" data-pc="pdf-close">Close</button></div>';
    }
    el.innerHTML = h;
  }
  function pcPdfSheetMsg(msg) {
    if (pc.exp) pc.exp.msg = msg;
    var n = $('pc-pdf-note'); if (n) n.textContent = msg || '';
  }
  function pcPdfSheetClose() {
    var el = $('pc-pdf-sheet'); if (el) el.remove();
    if (pc.exp && !pc.exp.busy) pc.exp = null;
  }
  function pcDownloadPdf() {
    var x = pc.exp; if (!x || !x.blob) return;
    var url = URL.createObjectURL(x.blob);
    var a = document.createElement('a'); a.href = url; a.download = x.name; a.rel = 'noopener'; a.style.display = 'none';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 60000);
    pcPdfSheetMsg('Downloaded ' + x.name + '.');
  }
  function pcSharePdf(auto) {
    var x = pc.exp; if (!x || !x.file) return;
    var data = { files: [x.file], title: x.name };
    if (x.mode === 'mail') {
      var parts = pcEmailParts(true);
      data.title = parts.subject;
      data.text = parts.body;
    }
    function failed(err) {
      if (err && err.name === 'AbortError') return;
      pcPdfSheetMsg(auto ? 'PDF ready. Tap Share to send or save it.' : 'Couldn\u2019t open the share sheet. Use Download instead.');
    }
    try { navigator.share(data).then(function () { pcPdfSheetMsg('Shared.'); }, failed); } catch (e) { failed(e); }
  }
  function pcExportPdf(mode) {
    if (pc.exp && pc.exp.busy) return;
    pc.exp = { busy: true, mode: mode };
    pcPdfSheet();
    pcBuildPdf(pc.pdfAll !== false).then(function (res) {
      var blob = new Blob([res.bytes], { type: 'application/pdf' });
      var file = null;
      try { file = new File([blob], res.name, { type: 'application/pdf' }); } catch (e) {}
      pc.exp = { busy: false, mode: mode, blob: blob, file: file, name: res.name, pages: res.pages, note: res.note, msg: '' };
      pc.exp.canShare = pcCanShareFiles(file);
      if (!pcOnScreen()) return;
      pcPdfSheet();
      if (pc.exp.canShare && (mode === 'mail' || pcIsPhone())) pcSharePdf(true);
      else if (mode !== 'mail') pcDownloadPdf();
    }, function (err) {
      pc.exp = { busy: false, error: (err && err.message) || 'Could not build the PDF.' };
      if (pcOnScreen()) pcPdfSheet();
    });
  }

  function pcDeleteChecklist() {
    if (!pc.id) return;
    if (!confirm('Delete this plan check checklist from this phone?')) return;
    pcMicStop(true);
    if (pc.fs) { pc.fs = false; var fsel = $('pc-fs'); if (fsel) fsel.remove(); document.documentElement.classList.remove('pc-fs-open'); document.body.classList.remove('pc-fs-open'); }
    pcPagePickClose();
    pcIdbDel(pcIdbKey(pc.drawing));
    pc.planBytes = null; pc.planBytesKey = '';
    pcReleasePdf();
    var store = pcLoadStore();
    store.list = store.list.filter(function (x) { return x.id !== pc.id; });
    pcSaveStore(store);
    state.pcRoute = { kind: 'list', id: '' };
    show('pc', false);
  }

  function pcBodyClick(e) {
    if (!pcOnScreen()) return;
    var b = e.target.closest('[data-pc]'); if (!b) return;
    var a = b.getAttribute('data-pc');
    if (a === 'new') { show('pc/new'); return; }
    if (a === 'mic') {
      pc.mic.target = (pc.annotCur && pcFindAnnot(pc.annotCur)) ? 'annot' : 'item';
      if (pc.mic.on) pcMicStop(); else pcMicStart();
      return;
    }
    if (a === 'annot-mic') {
      if (!pc.annotCur) return;
      pc.mic.target = 'annot';
      if (pc.mic.on) pcMicStop(); else pcMicStart();
      return;
    }
    if (a === 'proj') {
      pcReadDomMeta();
      pc.project = b.getAttribute('data-p') || 'Other';
      if (pc.project !== 'Other') pc.projectOther = '';
      pcAutosave(); pcRenderEditor(true); return;
    }
    if (a === 'to-pick') {
      pc.to = b.getAttribute('data-e') || '';
      var toEl = $('pc-to'); if (toEl) toEl.value = pc.to;
      pcAutosave(); return;
    }
    if (a === 'sel') { pcSelectItem(b.getAttribute('data-n')); return; }
    if (a === 'pin-sel') { e.stopPropagation(); pcSelectItem(b.getAttribute('data-n')); return; }
    if (a === 'annot-sel') {
      e.stopPropagation();
      pcSelectAnnot(b.getAttribute('data-id'));
      return;
    }
    if (a === 'add') {
      pcReadDomMeta();
      pc.items.push({ text: '', pin: null });
      pc.cur = pc.items.length;
      pc.mic.target = 'item';
      pcAutosave(); pcRenderEditor(true); return;
    }
    if (a === 'del-item') {
      pcReadDomMeta();
      if (pc.items.length <= 1) {
        pc.items = [{ text: '', pin: null }]; pc.cur = 1;
      } else {
        var delN = pc.cur;
        pc.items.splice(pc.cur - 1, 1);
        if (pc.cur > pc.items.length) pc.cur = pc.items.length;
        // Drop refs to deleted item; renumber higher refs
        pc.annots.forEach(function (an) {
          if (!(an.refItem >= 1)) return;
          if (an.refItem === delN) delete an.refItem;
          else if (an.refItem > delN) an.refItem -= 1;
        });
      }
      pcAutosave(); pcRenderEditor(true); return;
    }
    if (a === 'mode') {
      if (!pcHasPlan()) return;
      var m = b.getAttribute('data-mode') || 'view';
      if (m !== 'view' && m !== 'pin' && m !== 'text') m = 'view';
      pc.mode = (pc.mode === m && m !== 'view') ? 'view' : m;
      if (pc.mode !== 'view') pc.annotCur = '';
      if (pc.fs) { pcPaintOverlays(); return; }
      pcRenderEditor(true); return;
    }
    if (a === 'fs-open') { pcEnterFs(); return; }
    if (a === 'fs-done') { pcExitFs(); return; }
    if (a === 'zoom-in') { pcZoomBy(1.25); return; }
    if (a === 'zoom-out') { pcZoomBy(1 / 1.25); return; }
    if (a === 'zoom-fit') { pcZoomFit(); return; }
    if (a === 'fs-prev-item') {
      pcReadDomMeta();
      pc.cur = Math.max(1, pc.cur - 1);
      pc.annotCur = '';
      pc.mic.target = 'item';
      pcAutosave(); pcPaintOverlays(); pcFollowPinPage(); return;
    }
    if (a === 'fs-next-item') {
      pcReadDomMeta();
      pcEnsureItems();
      if (pc.cur >= pc.items.length) pc.items.push({ text: '', pin: null });
      pc.cur = pc.cur + 1;
      pcEnsureItems();
      pc.annotCur = '';
      pc.mic.target = 'item';
      pcAutosave(); pcPaintOverlays(); pcFollowPinPage(); return;
    }
    if (a === 'fs-item-mic') {
      pc.annotCur = '';
      pc.mic.target = 'item';
      if (pc.mic.on) pcMicStop(); else pcMicStart();
      pcPaintFsDock();
      return;
    }
    if (a === 'pin-clear') {
      pcEnsureItems();
      if (pc.items[pc.cur - 1]) pc.items[pc.cur - 1].pin = null;
      pcAutosave();
      if (pc.fs) { pcPaintOverlays(); return; }
      pcRenderEditor(true); return;
    }
    if (a === 'draw-clear') {
      if (!confirm('Remove the plan from this checklist? Pins and text notes on it will be cleared.')) return;
      if (pc.fs) pcExitFs();
      pcIdbDel(pcIdbKey(pc.drawing));
      pc.planBytes = null; pc.planBytesKey = '';
      pcReleasePdf();
      pc.drawing = ''; pc.drawingKind = '';
      pc.page = 1; pc.pdfPages = 1;
      pc.mode = 'view'; pc.annotCur = '';
      pc.items.forEach(function (it) { it.pin = null; });
      pc.annots = [];
      pcAutosave(); pcRenderEditor(true); return;
    }
    if (a === 'page-prev') { pcSetPage((pc.page || 1) - 1); return; }
    if (a === 'page-next') { pcSetPage((pc.page || 1) + 1); return; }
    if (a === 'page-pick') { pcPagePickOpen(); return; }
    if (a === 'page-pick-close') { pcPagePickClose(); return; }
    if (a === 'noop') return;
    if (a === 'page-go') { var pgo = parseInt(b.getAttribute('data-p'), 10); pcPagePickClose(); pcSetPage(pgo); return; }
    if (a === 'pin-go') { e.stopPropagation(); pcGoToPin(b.getAttribute('data-n')); return; }
    if (a === 'annot-del') {
      if (!pc.annotCur) return;
      pc.annots = pc.annots.filter(function (x) { return x.id !== pc.annotCur; });
      pc.annotCur = '';
      pc.mic.target = 'item';
      pcAutosave();
      if (pc.fs) { pcPaintOverlays(); return; }
      pcRenderEditor(true); return;
    }
    if (a === 'annot-done') {
      pcReadDomMeta();
      pc.annotCur = '';
      pc.mic.target = 'item';
      pcAutosave();
      if (pc.fs) { pcPaintOverlays(); return; }
      pcRenderEditor(true); return;
    }
    if (a === 'draw-tap') {
      if (pc._suppressTap) { pc._suppressTap = false; return; }
      if (e.target.closest('.pcpin') || e.target.closest('.pcannot')) return;
      if (pc.mode === 'pin') { pcPlacePinAt(e.clientX, e.clientY); return; }
      if (pc.mode === 'text') { pcPlaceTextAt(e.clientX, e.clientY); return; }
      return;
    }
    if (a === 'email') { pcBuildEmail(); return; }
    if (a === 'pdf-save') { pcReadDomMeta(); pcAutosave(); pcExportPdf('save'); return; }
    if (a === 'pdf-mail') { pcReadDomMeta(); pcAutosave(); pcExportPdf('mail'); return; }
    if (a === 'pdf-share') { pcSharePdf(false); return; }
    if (a === 'pdf-download') { pcDownloadPdf(); return; }
    if (a === 'pdf-close') { pcPdfSheetClose(); return; }
    if (a === 'pdf-pages') {
      pcReadDomMeta();
      pc.pdfAll = pc.pdfAll === false;
      lsSet('cc_pc_pdf_all', pc.pdfAll);
      pcRenderEditor(true); return;
    }
    if (a === 'annot-fs-dn' || a === 'annot-fs-up' || a === 'annot-fs-auto') {
      var anf = pc.annotCur ? pcFindAnnot(pc.annotCur) : null;
      if (!anf) return;
      if (a === 'annot-fs-auto') delete anf.fs;
      else {
        var curFs = pcAnnotFs(anf);
        if (!(curFs > 0)) return;
        anf.fs = Math.round(Math.max(0.5, Math.min(2000, curFs * (a === 'annot-fs-up' ? 1.2 : 1 / 1.2))) * 100) / 100;
      }
      pcAutosave();
      pcRepaintMarks();
      document.querySelectorAll('#screen-pc .pcfsval').forEach(function (el) { el.textContent = pcAnnotSizeLabel(anf); });
      return;
    }
    if (a === 'delete') { pcDeleteChecklist(); return; }
  }
  // Fullscreen item stepping: if the selected item is pinned on another page, turn to that page.
  function pcFollowPinPage() {
    var it = pc.items[pc.cur - 1];
    if (pc.fs && pc.drawingKind === 'pdf' && it && it.pin && (it.pin.page || 1) !== pc.page) pcSetPage(it.pin.page || 1);
  }
  function pcBodyInput(e) {
    if (!pcOnScreen()) return;
    var t = e.target;
    if (t && t.getAttribute && t.getAttribute('data-pc-annot-text')) {
      var id = t.getAttribute('data-pc-annot-text');
      var an = pcFindAnnot(id);
      if (an) {
        an.text = t.value;
        document.querySelectorAll('#screen-pc [data-pc-annot-text="' + id + '"]').forEach(function (o) { if (o !== t) o.value = t.value; });
        var preview = document.querySelector('.pcannot[data-id="' + id + '"] .pcannotbody');
        if (preview) preview.textContent = (t.value || '').trim() || 'Note\u2026';
        pcAutosave();
      }
      return;
    }
    if (t && t.id === 'pc-annot-ref') {
      var a2 = pc.annotCur ? pcFindAnnot(pc.annotCur) : null;
      if (a2) {
        var v = parseInt(t.value, 10);
        if (v >= 1) a2.refItem = v; else delete a2.refItem;
        pcAutosave();
        pcPaintOverlays();
      }
      return;
    }
    if (t && (t.id === 'pc-title-in' || t.id === 'pc-to' || t.id === 'pc-project-other' || t.getAttribute('data-pc-item'))) {
      if (t.getAttribute('data-pc-item')) {
        var n = parseInt(t.getAttribute('data-pc-item'), 10);
        if (n) {
          pcEnsureItems();
          while (pc.items.length < n) pc.items.push({ text: '', pin: null });
          pc.items[n - 1].text = t.value;
          // keep the other copy (editor list vs fullscreen dock) in step so a later DOM read can't bring back old text
          document.querySelectorAll('#screen-pc [data-pc-item="' + n + '"]').forEach(function (o) { if (o !== t) o.value = t.value; });
          if (n !== pc.cur) {
            document.querySelectorAll('#pc-items .pcitem').forEach(function (row) {
              row.classList.toggle('on', parseInt(row.getAttribute('data-pc-row'), 10) === n);
            });
            pc.cur = n;
            pc.mic.target = 'item';
            pcPaintMicStatus();
            pcPaintOverlays();
          }
        }
      } else {
        pcReadDomMeta();
      }
      pcAutosave();
    }
  }
  function pcBodyChange(e) {
    if (!pcOnScreen()) return;
    var t = e.target;
    if (t && t.id === 'pc-annot-ref') {
      pcBodyInput(e);
      return;
    }
    if (t && t.id === 'pc-draw-file') {
      var f = t.files && t.files[0];
      t.value = '';
      if (f) pcAttachDrawing(f);
    }
  }
  function pcBodyFocus(e) {
    if (!pcOnScreen()) return;
    var t = e.target;
    if (t && t.getAttribute && t.getAttribute('data-pc-item')) {
      var n = parseInt(t.getAttribute('data-pc-item'), 10);
      if (n && n !== pc.cur) {
        pc.cur = n;
        pc.mic.target = 'item';
        document.querySelectorAll('#pc-items .pcitem').forEach(function (row) {
          row.classList.toggle('on', parseInt(row.getAttribute('data-pc-row'), 10) === n);
        });
        pcPaintOverlays();
        pcPaintMicStatus();
      }
    }
    if (t && t.getAttribute && t.getAttribute('data-pc-annot-text')) {
      pc.mic.target = 'annot';
      pcPaintMicStatus();
    }
  }

  // Simple drag for text boxes (pointer) — also pans the fullscreen plan in Select mode
  (function pcAnnotDrag() {
    var drag = null;
    var pan = null;
    var pinch = null;
    function finger(e) { return e.touches ? e.touches[0] : e; }
    function pinchDist(t0, t1) {
      var dx = t0.clientX - t1.clientX, dy = t0.clientY - t1.clientY;
      return Math.sqrt(dx * dx + dy * dy) || 1;
    }
    function onDown(e) {
      if (!pcOnScreen()) return;
      // Pinch start (fullscreen)
      if (pc.fs && e.touches && e.touches.length === 2) {
        var t0 = e.touches[0], t1 = e.touches[1];
        pinch = {
          dist: pinchDist(t0, t1),
          zoom: pc.zoom || 1,
          cx: (t0.clientX + t1.clientX) / 2,
          cy: (t0.clientY + t1.clientY) / 2
        };
        pan = null; drag = null;
        return;
      }
      if (pc.mode !== 'view') return;
      var box = e.target.closest('.pcannot');
      if (box) {
        if (e.target.closest('textarea,select,button,a,input')) return;
        var id = box.getAttribute('data-id'); if (!id) return;
        var pt = finger(e);
        drag = { id: id, x0: pt.clientX, y0: pt.clientY, moved: false };
        return;
      }
      // Pan fullscreen plan when Select tool is active
      if (pc.fs && e.target.closest('#pc-fs-view') && !e.target.closest('.pcpin,.pcannot,textarea,select,button,a,input')) {
        var p = finger(e);
        pan = { x0: p.clientX, y0: p.clientY, lx: p.clientX, ly: p.clientY, t0: Date.now(), z0: pc.zoom || 1, panX: pc.panX || 0, panY: pc.panY || 0, moved: false };
      }
    }
    function onMove(e) {
      if (pinch && pc.fs && e.touches && e.touches.length >= 2) {
        if (e.cancelable) e.preventDefault();
        var t0 = e.touches[0], t1 = e.touches[1];
        var d = pinchDist(t0, t1);
        var factor = d / pinch.dist;
        var target = pcClampZoom(pinch.zoom * factor);
        var view = $('pc-fs-view'); if (!view) return;
        var rect = view.getBoundingClientRect();
        var mx = ((t0.clientX + t1.clientX) / 2) - rect.left;
        var my = ((t0.clientY + t1.clientY) / 2) - rect.top;
        var oldZ = pc.zoom || 1;
        var wx = (mx - (pc.panX || 0)) / oldZ;
        var wy = (my - (pc.panY || 0)) / oldZ;
        pc.zoom = target;
        pc.panX = mx - wx * target;
        pc.panY = my - wy * target;
        pcApplyZoomPan();
        return;
      }
      if (pan && pc.fs) {
        var p2 = finger(e);
        var dx = p2.clientX - pan.x0, dy = p2.clientY - pan.y0;
        pan.lx = p2.clientX; pan.ly = p2.clientY;
        if (!pan.moved && Math.abs(dx) + Math.abs(dy) < 6) return;
        pan.moved = true;
        if (e.cancelable) e.preventDefault();
        pc.panX = pan.panX + dx;
        pc.panY = pan.panY + dy;
        pcApplyZoomPan();
        return;
      }
      if (!drag) return;
      var pt = finger(e);
      var ddx = pt.clientX - drag.x0, ddy = pt.clientY - drag.y0;
      if (!drag.moved && Math.abs(ddx) + Math.abs(ddy) < 8) return;
      drag.moved = true;
      if (e.cancelable) e.preventDefault();
      var ids = pcActiveDrawIds();
      var stage = $(ids.stage); if (!stage) return;
      var rect = stage.getBoundingClientRect();
      var an = pcFindAnnot(drag.id); if (!an) return;
      an.x = pcClampPct(((pt.clientX - rect.left) / rect.width) * 100);
      an.y = pcClampPct(((pt.clientY - rect.top) / rect.height) * 100);
      document.querySelectorAll('.pcannot[data-id="' + drag.id + '"]').forEach(function (el) {
        el.style.left = an.x + '%'; el.style.top = an.y + '%';
      });
    }
    function onUp(e) {
      if (pinch && (!e.touches || e.touches.length < 2)) pinch = null;
      if (pan) {
        if (pan.moved) { pc._suppressTap = true; setTimeout(function () { pc._suppressTap = false; }, 450); }
        // Swipe = quick, mostly-horizontal flick while the plan is at fit (100% or less) with the Select tool.
        var sdx = pan.lx - pan.x0, sdy = pan.ly - pan.y0;
        if (pan.moved && pc.fs && pc.mode === 'view' && pc.drawingKind === 'pdf' && pan.z0 <= 1.01 && (pc.zoom || 1) <= 1.01 &&
            Math.abs(sdx) > 70 && Math.abs(sdx) > Math.abs(sdy) * 2 && Date.now() - pan.t0 < 600) {
          var to = (pc.page || 1) + (sdx < 0 ? 1 : -1);
          pcZoomFit();
          if (to >= 1 && to <= (pc.pdfPages || 1)) pcSetPage(to);
        }
        pan = null;
      }
      if (!drag) return;
      if (drag.moved) pcAutosave();
      drag = null;
    }
    var root = $('screen-pc'); if (!root) return;
    root.addEventListener('mousedown', onDown);
    root.addEventListener('touchstart', onDown, { passive: true });
    window.addEventListener('mousemove', onMove, { passive: false });
    window.addEventListener('touchmove', onMove, { passive: false });
    window.addEventListener('mouseup', onUp);
    window.addEventListener('touchend', onUp);
    window.addEventListener('touchcancel', onUp);
  })();

  // Wheel zoom over fullscreen plan
  (function pcFsWheel() {
    var root = $('screen-pc'); if (!root) return;
    root.addEventListener('wheel', function (e) {
      if (!pc.fs || !pcOnScreen()) return;
      if (!e.target.closest || !e.target.closest('#pc-fs-view')) return;
      e.preventDefault();
      var factor = e.deltaY < 0 ? 1.12 : (1 / 1.12);
      pcZoomBy(factor, e.clientX, e.clientY);
    }, { passive: false });
  })();

  // Wire once on #screen-pc so fullscreen overlay (sibling of #pc-body) receives events
  (function () {
    var root = $('screen-pc'); if (!root) return;
    root.addEventListener('click', pcBodyClick);
    root.addEventListener('input', pcBodyInput);
    root.addEventListener('focusin', pcBodyFocus);
    root.addEventListener('change', pcBodyChange);
  })();
  document.addEventListener('visibilitychange', function () {
    if (document.hidden && pc.mic.on) pcMicStop(true);
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && pc.fs && pcOnScreen()) { e.preventDefault(); pcExitFs(); }
  });

  /* ---------------- Task Manager (#tm, #tm/today, #tm/sugg; v131) ---------------- */
  // v131: the daily task list + Suggestions box (v124, at the top of Home) moved behind a Home tile 'Task Manager' (layout item 'tm',
  // movable / foldable like every other tile; saved layouts get it too at the top of Home via hlNormalize). #tm shows two buttons,
  // Today and Suggestions (with counts). Both lists are collapsible rows: a short title (2-4 words); tap it to see everything.
  // Lives on THIS PHONE only (localStorage 'cc.tasks.v1', same key and shape as v124 plus three fields, migrated in place:
  //   title (short general title; auto-made from the text when missing, editable), tAuto (true = title still follows the text),
  //   notes (free text)). Nothing here touches the passcode, Plan Checks, layout or cache keys.
  //  - Today: open tasks due today or earlier (earlier = "carried Nd"). Top 3 = up to 3 pinned tasks, first, in a copper-outlined block.
  //    Then the rest of today, "Done today N" (tap to see / un-do), then Upcoming (future-dated) as its own collapsible group.
  //    Add by typing or the mic (words go in the box; nothing is saved until Add), with a date (Today / Tomorrow / any day ahead).
  //    Check = done. Swipe a closed row left = delete (Undo). Expanded row: full text, date, notes, Top 3, carry-over, Done / Edit / Delete.
  //  - Suggestions: open items from the Project Tasks Master list (API action=suggest once backend/tasks.patch is deployed, else
  //    suggestions.json in this repo; an item may carry source 'goal' = long-term goal). Expanded row: full text, source, project,
  //    due, with Add to Today / Snooze 3d / Dismiss. Nothing is added unless tapped.
  var TK_KEY = 'cc.tasks.v1', TK_SUGG_KEY = 'cc.tasks.sugg.v1', TK_MAX_PINS = 3, TK_SNOOZE_DAYS = 3;
  var tk = { d: null, editId: '', exp: {}, sexp: {}, showDone: false, msg: '', msgUndo: null, msgT: 0, rec: null, on: false, base: '', committed: '', interim: '', micMsg: '',
    sugg: null, suggSrc: '', suggLoading: false, suggTried: '', suggErr: false, bound: false, day: '', titleTouched: false };
  function tkPad(n) { return (n < 10 ? '0' : '') + n; }
  function tkIso(d) { return d.getFullYear() + '-' + tkPad(d.getMonth() + 1) + '-' + tkPad(d.getDate()); }
  function tkToday() { return tkIso(new Date()); }
  function tkAddDays(iso, n) { var p = iso.split('-'); return tkIso(new Date(+p[0], +p[1] - 1, +p[2] + n)); }
  function tkDays(a, b) {       // whole days from a to b (YYYY-MM-DD)
    var pa = a.split('-'), pb = b.split('-');
    return Math.round((Date.UTC(+pb[0], +pb[1] - 1, +pb[2]) - Date.UTC(+pa[0], +pa[1] - 1, +pa[2])) / 864e5);
  }
  function tkValidIso(s) { return typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s); }
  function tkNice(iso) {
    var t = tkToday(), n = tkDays(t, iso);
    if (n === 0) return 'Today'; if (n === 1) return 'Tomorrow'; if (n === -1) return 'Yesterday';
    var p = iso.split('-'), d = new Date(+p[0], +p[1] - 1, +p[2]);
    return d.toLocaleDateString('en-US', { weekday: n > 0 && n < 7 ? 'short' : undefined, month: 'short', day: 'numeric' });
  }
  function tkLong(iso) {
    if (!tkValidIso(iso)) return '';
    var p = iso.split('-'), d = new Date(+p[0], +p[1] - 1, +p[2]);
    return d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: d.getFullYear() === new Date().getFullYear() ? undefined : 'numeric' });
  }
  function tkNewId() { return 't' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }

  /* ---- Short titles: "Need to follow up on the drainage at Mathiesen, water ponding ..." -> "Mathiesen drainage" ----
   * Project name first (as written in the task: Terra Vi, MarVal, Boyer Matheson, Mathiesen/Matheson, Mariposa Gold Mine, YSF,
   * Brocchini; or the suggestion's project tag), then the main subject (a construction / admin topic word, else a capitalized name,
   * else the first word that is not filler), plus a document word right after it (comments, memo, checklist, package ...). 2-4 words. */
  var TK_PROJ_RE = /\b(boyer[\s-]+mat{1,2}h?i?e?s[eo]n|terra[\s-]?vi|mar[\s-]?val|mariposa(?:\s+gold\s+mine)?|mat{1,2}h?i?e?s[eo]n|ysf|brocchini)\b/i;
  var TK_STOP = {};
  ('a an the to for of and or but nor with without on in at by from about into onto over under up out off as is are was were be been being am ' +
    'it its it\'s this that these those there here then than so such very just really also still maybe please pls asap re regarding per via ' +
    'i me my mine we us our you your he him his she her they them their who whom which what when where why how ' +
    'need needs needed want wants wanted have has had having do does did doing done get gets got getting make makes made sure ' +
    'will would should could can may might must shall let lets let\'s going gonna gotta try trying remember reminder note notes ' +
    'some any all more most much many few lot lots thing things stuff etc ok okay yes no not new old other another each every ' +
    'today tomorrow tonight yesterday morning afternoon evening night week weeks day days month months year next last this ' +
    'monday tuesday wednesday thursday friday saturday sunday mon tue tues wed thu thur thurs fri sat sun ' +
    'january february march april may june july august september october november december jan feb mar apr jun jul aug sep sept oct nov dec ' +
    'issue issues item items stuff situation problem one two three four five six seven eight nine ten first second third again back still already ' +
    'like around regarding w/ w/o vs versus if whether because since while after before until during between behind across').split(' ').forEach(function (w) { TK_STOP[w] = 1; });
  var TK_VERBS = {};
  ('call calls email emails text texts send sent check checks follow followup follow-up review look looking talk ask tell find fix finish finalize ' +
    'submit resubmit respond reply write update upload download schedule reschedule locate file lock clarify confirm figure see go come take put set start ' +
    'discuss meet coordinate prepare draft complete work handle reach contact pick drop buy order pay sign print scan read add remove move ' +
    'change create build help give keep bring hold verify sort clean book plan think decide approve request') .split(/\s+/).forEach(function (w) { if (w) TK_VERBS[w] = 1; });
  var TK_TOPICS = ['storm drain', 'drainage', 'drain', 'stormwater', 'swale', 'ponding', 'grading', 'erosion', 'swppp', 'hydraulics', 'hydrology', 'culvert',
    'retaining wall', 'keyway', 'footings', 'footing', 'foundation', 'survey', 'utility', 'utilities', 'sewer', 'septic', 'water line', 'waterline', 'water main',
    'well', 'pump', 'paving', 'asphalt', 'concrete', 'curb', 'sidewalk', 'driveway', 'roadway', 'road', 'traffic control', 'ttcp', 'closure', 'lighting', 'lights',
    'site plan', 'site walk', 'plot plan', 'permit', 'permits', 'encroachment', 'easement', 'boundary', 'topo', 'staking', 'inspection', 'punch list', 'punchlist',
    'bid', 'bids', 'contract', 'proposal', 'invoice', 'invoices', 'billing', 'payment', 'change order', 'fire', 'hydrant', 'landscaping', 'irrigation', 'fence',
    'gate', 'roof', 'plumbing', 'electrical', 'hvac', 'insurance', 'taxes', 'tax', 'loan', 'lease', 'rent', 'budget', 'design'];
  var TK_DOCS = [['comments', 1], ['comment', 1], ['memo', 1], ['checklist', 1], ['package', 1], ['report', 1], ['write-up', 1], ['writeup', 1], ['submittal', 1],
    ['resubmittal', 1], ['response', 1], ['estimate', 1], ['quote', 1], ['rfi', 1], ['letter', 1], ['application', 1], ['tie-in', 1], ['exhibit', 1], ['calcs', 1],
    ['plan check', 2], ['plan-check', 2], ['plans', 2], ['plan set', 2], ['drawings', 2], ['pdfs', 2], ['pdf', 2], ['photos', 2], ['map', 2], ['form', 2], ['meeting', 2], ['schedule', 2]];
