      var doc = nxOk ? { at: topic.end, w: nx[1] } : tkFind1(TK_DOC_RE.filter(function (x) { return topic.w.toLowerCase().indexOf(x[0]) < 0; }), rest, topic.end, Math.min(rest.length, topic.end + 40));
